fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    // Create a new vector to hold the clipped values
    let mut result = Vec::with_capacity(arr.len());

    // Check if the bounds are valid for clipping
    if min_val <= max_val {
        // Clip each element to the range [min_val, max_val]
        for &value in arr {
            let clipped_value = if value < min_val {
                min_val
            } else if value > max_val {
                max_val
            } else {
                value
            };
            result.push(clipped_value);
        }
    } else {
        // If min_val > max_val, fill the result with max_val
        result.resize(arr.len(), max_val);
    }

    result
}